let C = "<Bb^7 F^7 Gm9 Dm9 Bb^7 Am7 Gm9 Dm9>"
let D = "<Dm9 Am7 Dm9 Am7 Gm9 Dm9 Bb^7 Am7>"
// phrase order: A B A C | A D B A
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, A], [8, D], [8, B], [8, A])

// Two cycles per line, four lines per phrase.
let line = (a, b, c, d) => cat(n(a), n(b), n(c), n(d)).slow(2)
let cello = arrange(
  [8, line("0 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ [0 -1] ~ ~ ~", "~ ~ 3 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ 0 ~", "0 ~ 1 ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~", "~ ~ ~ ~ 4 ~ ~ ~ 3 ~ 2 ~ ~ ~ 0 ~")],
  [8, line("3 ~ ~ ~ 4 ~ ~ ~ 5 ~ ~ ~ 4 ~ 3 ~", "~ ~ 2 ~ ~ ~ 3 ~ ~ ~ 4 ~ ~ ~ ~ ~", "5 ~ ~ ~ [4 3] ~ 2 ~ ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ 2 ~ ~ ~ 1 ~ ~ ~")],
  [8, line("~ ~ 0 ~ ~ ~ 2 ~ ~ ~ 4 ~ ~ ~ 3 ~", "2 ~ ~ ~ ~ ~ 1 ~ 0 ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 3 ~ 2 ~ ~ ~ 1 ~ 0 ~ ~ ~", "-1 ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("4 ~ ~ ~ ~ ~ 3 ~ 4 ~ ~ ~ 5 ~ ~ ~", "6 ~ ~ ~ 5 ~ ~ ~ 4 ~ 3 ~ ~ ~ ~ ~", "~ ~ 2 ~ ~ ~ 4 ~ ~ ~ 3 ~ ~ ~ 2 ~", "1 ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("0 ~ ~ 1 ~ ~ 2 ~ ~ ~ ~ ~ 1 ~ ~ ~", "~ ~ 3 ~ ~ ~ ~ ~ 2 ~ 1 ~ 0 ~ ~ ~", "~ ~ ~ ~ 4 ~ ~ 3 ~ ~ 2 ~ ~ ~ ~ ~", "3 ~ ~ ~ 2 ~ ~ ~ 1 ~ ~ ~ 0 ~ ~ ~")],
  [8, line("~ ~ ~ ~ 2 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ 0 ~ ~ ~ ~ ~ ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("2 ~ ~ 3 ~ ~ 4 ~ ~ 5 ~ ~ 4 ~ ~ ~", "~ ~ 3 ~ ~ ~ 5 ~ ~ ~ 6 ~ ~ ~ 5 ~", "4 ~ ~ ~ 3 ~ ~ 2 ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ 1 ~ ~ ~ 0 ~")],
  [8, line("0 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ 0 ~ ~ ~ -1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
)

// the harp answers where the cello rests: a different pick in each phrase
let touch = arrange(
  [8, line("~ ~ ~ 4 ~ ~ 2 ~ ~ ~ ~ ~ ~ 6 ~ ~", "~ ~ ~ ~ ~ 3 ~ ~ ~ ~ 5 ~ ~ ~ ~ ~", "~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 3 ~", "~ ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 4 ~ ~ ~ ~")],
  [8, line("~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 5 ~ ~ ~", "~ ~ ~ 2 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~", "~ ~ 6 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 2 ~", "~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~ 5 ~ ~ ~")],
  [8, line("~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~ ~", "~ 6 ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~", "~ ~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~")],
  [8, line("~ ~ 2 ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~", "~ ~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~", "6 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~")],
  [8, line("~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ ~ ~", "~ 3 ~ ~ ~ ~ 5 ~ ~ ~ ~ ~ ~ ~ 4 ~", "~ ~ ~ ~ ~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~", "~ ~ 6 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 2 ~ ~ ~ ~ ~", "~ ~ ~ 6 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~")],
  [8, line("~ 2 ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~", "~ ~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~", "~ ~ 4 ~ ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 5 ~", "~ ~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~")],
  [8, line("~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
)

stack(
  // 0: low strings and the cello
  chord(P).voicing().mode("below:g3")
    .s("supersaw").unison(2).detune(.2).attack(2).clip(.9).release(.3).gain(.16)
    .lpf(sine.range(500, 1100).slow(32)).room(.9).roomsize(6).orbit(2),
  cello.scale("d3:aeolian")
    .s("sawtooth").attack(.25).release(1.6).gain(.5).vib("5.2:.2")
    .lpf(900).lpenv(2).lpa(.3).lpd(.8).room(.8).roomsize(6).orbit(2),
  // 1: a harp touches the chord, high and far
  layer(1, touch.chord(P).voicing().mode("above:d4")
    .s("harp").gain(.4).room(.9).roomsize(6).orbit(2))
).postgain(.85)
`,wE=`// clash-of-banners - A dorian, 140 bpm. mood: action, epic.
// A 4v4 skirmish. Driving war drums, a string ostinato in sixteenths, short
// brass stabs. Even the calm level keeps moving: this is a fight track.
// Fourteen sections of eight cycles (3m12s before it repeats): four chord
// journeys, and the bass riff, the stabs and the whistle never repeat a bar.
setcpm(140 / 4)

let A = "<Am7 D7 Am7 G^7 Am7 D7 Em7 Am7>"
let B = "<Am7 G^7 C^7 D7 Am7 Em7 D7 G^7>"
let C = "<Em7 Am7 D7 G^7 C^7 D7 Bm7 Em7>"
let D = "<Am7 C^7 G^7 D7 Em7 G^7 D7 Am7>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, B], [8, C], [8, D], [8, B], [8, A])

// the whistle's tune: eight cycles
let tune = "<[7 ~ 6 4 ~ 4 2 ~] [4 ~ 2 0 ~ 0 2 4] [6 ~ 4 2 ~ 2 0 ~] [2 ~ 4 6 ~ 7 6 4] [7 ~ 7 6 ~ 4 6 7] [4 ~ 6 4 ~ 2 0 ~] [2 4 6 4 2 ~ 0 ~] [0 ~ ~ 2 4 ~ ~ ~]>"
let whistle = arrange([8, tune], [8, tune.add(2)], [8, tune.rev()], [8, tune.add(-2)], [8, tune.add(3)],
  [8, tune.rev().add(2)], [8, tune], [8, tune.add(-2).rev()], [8, tune.add(2).rev()], [8, tune.add(3)],
  [8, tune.rev()], [8, tune.add(-2)], [8, tune.add(2)], [8, tune])

stack(
  // 0: sixteenth-note string pulse on the root, a bass line
  n("0 0 [0 7] 0 0 [0 7] 0 0 0 [0 7] 0 [4 3] 0 0 [2 0]".add("<0 0 1 0 0 0 -1 0 0 2 0 0 -2 0 0 3>")).scale("a2:dorian")
    .s("sawtooth").decay(.1).sustain(0).release(.05).gain(.45).lpf(ref(() => 600 + INTENSITY * 500)).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:e4")
    .s("supersaw").unison(2).detune(.2).attack(.1).clip(.9).release(.15).gain(.22)
    .lpf(1400).room(.4).roomsize(6).orbit(2),
  s("timp:1 ~ ~ ~ timp:1 ~ ~ ~").gain(.5).room(.3),
  // 1: frame drums drive the offbeat, the lute stabs
  layer(1, stack(
    s("~ frame:0 ~ frame:2 ~ frame:0 ~ frame:2").gain(.45),
    n("<0 ~ 2 ~>*4").chord(P).voicing().mode("above:a3").s("strum").gain(.5).room(.3))),
  // 2: war drums, snare, brass stabs
  layer(2, stack(
    s("taiko:0 ~ taiko:1 taiko:0 ~ taiko:1 taiko:0 ~").gain(.8).room(.3),
    s("~ ~ snare:0 ~ ~ ~ snare:1 ~").gain(.4),
    n("[0 ~ ~ 0 ~ ~ 2 ~] [~ ~ 4 ~ ~ 2 ~ ~]".add("<0 2 0 3 4 0 -2 0>")).scale("a3:dorian")
      .s("sawtooth").attack(.01).release(.2).gain(.5).lpf(1000).lpenv(2).lpd(.15).room(.3).roomsize(6).orbit(2))),
  // 3: crash on the bar, the whistle screams the tune
  layer(3, stack(
    s("crash:1 ~ ~ ~ ~ ~ ~ ~").gain(.35),
    n(whistle).scale("a3:dorian")
      .s("whistle").gain(.5).attack(.02).release(.3).lpf(2800).room(.4).roomsize(6).orbit(2)))
).postgain(.31)
`,TE=`// ember-deep - C aeolian with a phrygian bII (Db) on purpose, 100 bpm.
// mood: dark, action. Volcanic menace: low brass, anvil hits, a grinding ostinato
// that never quite resolves. Db is the heat, and the only note outside the key.
// Ten sections of eight cycles (3m12s before it repeats): four chord
// journeys, and the ostinato and the brass stabs keep changing their notes.
setcpm(100 / 4)

let A = "<Cm9 Db^7 Cm9 Gm7 Fm9 Db^7 Ab^7 Bb>"
let B = "<Fm9 Cm9 Db^7 Cm9 Gm7 Ab^7 Db^7 Bb>"
let C = "<Cm9 Gm7 Ab^7 Bb Cm9 Fm9 Db^7 Gm7>"
let D = "<Db^7 Cm9 Bb Ab^7 Fm9 Gm7 Cm9 Db^7>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, C])

stack(
  // 0: low brass swells and the sub
  chord(P).voicing().mode("below:g3")
    .s("sawtooth").attack(.7).clip(.9).release(.2).gain(.3)
    .lpf(500).lpenv(3).lpa(.5).lpd(1.2).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(1)).s("sine").attack(.05).release(1.2).gain(.4),
  s("anvil:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.35).room(.6).roomsize(6).orbit(2),
  // 1: the grinding ostinato
  layer(1, n("0 0 [0 1] 0 0 3 0 [0 1]".fast(2).add("<0 0 0 0 0 0 3 0 0 0 0 0 -2 0 3 1>")).scale("c2:aeolian")
      .s("sawtooth").decay(.12).sustain(.2).release(.05).gain(.6)
      .lpf(sine.range(300, 900).slow(8)).lpq(6).distort("1:.4")),
  // 2: war drums and anvil
  layer(2, stack(
    s("taiko:0 ~ ~ taiko:1 ~ taiko:0 ~ ~").gain(.8).room(.4),
    s("anvil:1 ~ ~ ~ ~ anvil:2 ~ ~").gain(.4).room(.5))),
  // 3: brass stabs and the choir
  layer(3, stack(
    n("0 ~ ~ 0 ~ ~ 4 ~".add("<0 0 2 0 3 0 -1 0 4 2 0 0 -2 0 3 2>")).scale("c3:aeolian").s("sawtooth").attack(.02).release(.1).gain(.4)
      .lpf(1000).lpenv(2).lpd(.3).room(.4).roomsize(6).orbit(2),
    chord(P).voicing().mode("below:c5").s("sawtooth").lpq(4).attack(.4).clip(.9).release(.2).gain(.2)
      .lpf(2000).room(.8).roomsize(6).orbit(2)))
).postgain(.27)
`,EE=`// first-light - D lydian, 76 bpm. mood: atmospheric, adventurous.
// Pastoral morning before everything went wrong: harp over warm strings, the
// raised 4th (G#) as hope. Level 0 is the morning, level 1 the walk.
// Eight phrases of eight cycles (3m22s before it repeats): the chords change
// in four ways.
setcpm(76 / 4)

let A = "<D^9 E Bm7 A D^9 E F#m7 A>"
let B = "<Bm7 C#m7 D^9 E F#m7 Bm7 E A>"
let C = "<D^9 F#m7 Bm7 C#m7 D^9 E A D^9>"
let D = "<F#m7 Bm7 E A D^9 C#m7 Bm7 E>"
// phrase order: A B A C | A' D B A
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, A], [8, D], [8, B], [8, A])

stack(
  // 0: strings and a soft bass
  chord(P).voicing().mode("below:a4")
    .s("supersaw").unison(3).detune(.25).attack(1.4).clip(.9).release(.25).gain(.18)
    .lpf(sine.range(700, 1800).slow(16)).room(.8).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.08).release(1.2).gain(.45),
  // 1: the harp starts walking, a frame drum keeps time far off
  layer(1, stack(
    n("0 2 4 [5 4] 2 4 6 [4 2]").chord(P).voicing().mode("above:d3")
      .s("harp").gain(.55).room(.6).roomsize(6).orbit(2),
    s("frame:3 ~ ~ ~ frame:3 ~ [~ frame:3] ~").gain(.35).room(.4)))
).postgain(.4)
`,DE=`// glass-dunes - D phrygian dominant ("spanish" in Strudel scale names), 66 bpm. mood: epic, mysterious.
// A warm, wide desert at dusk: a low drone, a soft triangle pad and a plucked
// harp that tells four slow tales over it. Nothing blows and nothing is higher
// than B4 except a few far bells. Later layers add a strummed figure, a low
// triangle answer and a muffled drum.
// Eight sections of eight cycles (about 3m52s per pass): the pad walks
// four roads and the harp sings a different tale on each.
setcpm(66 / 4)

let A = "<D Eb D Gm D Eb Gm D>"
let B = "<Gm D Eb D Gm Eb D D>"
let C = "<D Gm Eb D Gm Eb Gm D>"
let E = "<Eb D Gm Gm D Eb D D>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, E], [8, B], [8, C], [8, A])

// four tales, one bar of eight steps each, over two cycles
let tale1 = "0 ~ 2 ~ 1 ~ 0 ~ | ~ 2 ~ 3 ~ 4 ~ 2 ~"
let tale2 = "4 ~ 3 ~ 2 ~ ~ 1 | 0 ~ ~ 2 ~ 1 ~ ~"
let tale3 = "~ 0 ~ 1 ~ 3 ~ 2 | 4 ~ 4 ~ 3 ~ 2 ~"
let tale4 = "2 ~ ~ 4 ~ 3 ~ ~ | 1 ~ 2 ~ 0 ~ ~ ~"
let walk = cat(tale1, tale2, tale3, tale4).slow(2)
let lead = arrange([8, walk], [8, walk.add(-2)], [8, walk.rev()], [8, walk.add(1)],
  [8, walk.add(-2)], [8, walk.rev().add(1)], [8, walk.add(1).rev()], [8, walk])

stack(
  // 0: drone, pad and the harp
  note("d1").s("sine").attack(2).release(3).gain(.5),
  note("d2").s("triangle").attack(2).release(3).gain(.3),
  chord(P).voicing().mode("below:a4")
    .s("triangle").attack(1.2).release(2.5).gain(.2)
    .lpf(1400).room(.9).roomsize(6).orbit(2),
  n(lead).scale("d4:spanish")
    .s("harp").gain(.6).release(1.2).room(.8).roomsize(6).orbit(2),
  // 1: a strummed figure and sparse far bells
  layer(1, stack(
    chord(P).voicing().mode("below:a4").segment(4).s("strum").gain(.22).room(.5).roomsize(6).orbit(2),
    note("<d5 ~ a5 ~ f#5 ~ c6 ~>").s("bells").gain(.2).room(.9).roomsize(6).orbit(2))),
  // 2: a low triangle answers the harp, a muffled drum under it
  layer(2, stack(
    s("taiko:0 ~ ~ ~ ~ ~ taiko:1 ~").gain(.5).lpf(900).room(.5),
    n(lead.add(-7)).scale("d4:spanish").s("triangle")
      .attack(.05).release(.8).gain(.35).room(.6).roomsize(6).orbit(2)))
).postgain(.33)
`,OE=`// hall-of-champions - D aeolian with a harmonic-minor V (C# in the A chord), 128 bpm.
